import { useId, type ReactNode } from 'react';
import { IconAlert } from '../icons/alert';
import './field.css';

export interface FieldIds {
  inputId: string;
  labelId: string;
  hintId: string;
  errorId: string;
}

export function useFieldIds(id?: string): FieldIds {
  const base = useId();
  return {
    inputId: id ?? `${base}-input`,
    labelId: `${base}-label`,
    hintId: `${base}-hint`,
    errorId: `${base}-error`,
  };
}

/** The `aria-describedby` value for a field: the error first, then the hint. */
export function describedBy(
  ids: FieldIds,
  hint?: ReactNode,
  error?: ReactNode,
): string | undefined {
  return (
    [error ? ids.errorId : null, hint ? ids.hintId : null].filter(Boolean).join(' ') || undefined
  );
}

interface FieldShellProps {
  ids: FieldIds;
  label: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  required?: boolean;
  /** Render the label as a `<label for>` (native inputs) or a plain element referenced by id. */
  labelAs?: 'label' | 'span';
  /** Hide the label visually; it still names the control. */
  hideLabel?: boolean;
  /** Content on the label row's right, such as a character counter. */
  aside?: ReactNode;
  className?: string;
  children: ReactNode;
}

/** Label, hint and error around a control, wired together with ids. */
export function FieldShell({
  ids,
  label,
  hint,
  error,
  required,
  labelAs = 'label',
  hideLabel = false,
  aside,
  className,
  children,
}: FieldShellProps) {
  const labelContent = (
    <>
      {label}
      {required ? (
        <>
          {' '}
          <span className="atl-field__required">(required)</span>
        </>
      ) : null}
    </>
  );
  const labelClass = hideLabel ? 'atl-field__label atl-visually-hidden' : 'atl-field__label';
  return (
    <div
      className={['atl-field', className].filter(Boolean).join(' ')}
      data-invalid={error ? '' : undefined}
    >
      <div className="atl-field__top">
        {labelAs === 'label' ? (
          <label id={ids.labelId} htmlFor={ids.inputId} className={labelClass}>
            {labelContent}
          </label>
        ) : (
          <span id={ids.labelId} className={labelClass}>
            {labelContent}
          </span>
        )}
        {aside}
      </div>
      {children}
      {hint ? (
        <p id={ids.hintId} className="atl-field__hint">
          {hint}
        </p>
      ) : null}
      {error ? (
        <p id={ids.errorId} className="atl-field__error">
          <IconAlert size={16} />
          <span>{error}</span>
        </p>
      ) : null}
    </div>
  );
}

@layer atlas.components {
  .atl-field {
    display: grid;
    gap: var(--space-2xs);
    min-width: 0;
  }

  .atl-field__top {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--space-s);
  }

  .atl-field__label {
    font-weight: 600;
    font-size: var(--step-0);
  }

  .atl-field__required {
    color: var(--ink-soft);
    font-weight: 400;
    font-size: var(--step--1);
  }

  .atl-field__hint {
    color: var(--ink-soft);
    font-size: var(--step--1);
    max-width: 60ch;
  }

  .atl-field__error {
    display: flex;
    align-items: flex-start;
    gap: var(--space-2xs);
    color: var(--port);
    font-size: var(--step--1);
    font-weight: 550;
  }

  .atl-field__error svg {
    flex: none;
    margin-top: 0.1em;
  }

  /* The shared look of a text-like control box. */
  .atl-control-box {
    display: flex;
    align-items: center;
    min-height: 44px;
    border-radius: var(--radius-control);
    background: var(--sea-1);
    box-shadow: inset 0 0 0 1px var(--edge);
    transition: box-shadow var(--dur-tick) var(--ease-anchor);
  }

  .atl-control-box:hover {
    box-shadow: inset 0 0 0 1px var(--ink-soft);
  }

  .atl-control-box:focus-within {
    box-shadow:
      inset 0 0 0 1px var(--chart-magenta),
      0 0 0 2px var(--magenta-wash);
  }

  .atl-field[data-invalid] .atl-control-box {
    box-shadow: inset 0 0 0 2px var(--port);
  }

  .atl-field[data-invalid] .atl-control-box:focus-within {
    box-shadow:
      inset 0 0 0 2px var(--port),
      0 0 0 3px var(--magenta-wash);
  }

  @media (forced-colors: active) {
    .atl-control-box {
      border: 1px solid FieldText;
    }
  }
}
